def is_simple_power(x, n):
    if x == 1:
        return True  # 1 is a power of any number (n**0)
    if n <= 1:
        return False  # 0 and 1 are only simple powers of themselves
    power = 1
    while power < x:
        power *= n
    return power == x
```
