def minPath(grid, k):
    N = len(grid)
    def dfs(x, y, path):
        if len(path) == k:
            return path
        min_path = None
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = dfs(nx, ny, path + [grid[nx][ny]])
                if min_path is None or new_path < min_path:
                    min_path = new_path
        return min_path

    min_lex_path = None
    for i in range(N):
        for j in range(N):
            path = dfs(i, j, [grid[i][j]])
            if min_lex_path is None or path < min_lex_path:
                min_lex_path = path
    return min_lex_path
