def do_algebra(operator, operand):
    # Start with the first operand
    result = operand[0]

    # Iterate through the operators and corresponding operands
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            # Ensure no division by zero
            if operand[i + 1] == 0:
                raise ValueError("Division by zero is not allowed.")
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {operator[i]}")

    return result

# Example usage:
